{"check_build":{"code":"script({title:"Piplup — A Very Proud Little Penguin",description:"A large, round Piplup with a sapphire hood, twin white face patches, sparkling eyes, a little open golden beak, two snowy chest buttons, webbed feet and an exuberantly raised flipper. A three-point tail finishes the back.",palette:{hood:"blue",body:"medium azure",snow:"white",gold:"yellow",ink:"black"}});
const P=(part,x,y,z,colour,turn=0)=>place({part,at:[x,y,z],colour,turn});
const B=(x,y,z,w,h,d,colour)=>box({at:[x,y,z],size:[w,h,d],colour,interior:"solid"});
const bodySizes=[[12,10],[16,12],[18,14],[20,16],[20,16],[20,16],[20,16],[18,14],[18,14],[16,12],[14,10],[12,10]];
const headSizes=[[16,12],[20,16],[22,18],[24,20],[26,22],[26,22],[26,22],[26,22],[26,22],[24,20],[22,18],[20,16],[16,12],[12,8],[8,6]];
function mask(x,y){const a=Math.abs(x+1);return ((a-6)/6)**2+((y+1-59)/17)**2<1||(y<56&&y>43&&a<7)?"white":"blue";}
function shell(sizes,y0,isHead){const mass=[],skin=[];for(let j=0;j<sizes.length;j++){const [w,d]=sizes[j],y=y0+3*j,l=-w/2,f=-d/2,prev=sizes[Math.max(0,j-1)],next=sizes[Math.min(sizes.length-1,j+1)];const c=isHead?"blue":"medium azure";for(let i=0;i<w/2;i++){const x=l+2*i,k=Math.min(i,w/2-1-i),cut=k===0?4:k===1?2:0,depth=d-2*cut;if(depth<=0)continue;const z=f+cut,fc=isHead?mask(x,y):(y>=32||(y>=29&&Math.abs(x+1)<4)?"blue":"medium azure");mass.push(B(x,y,z,2,3,depth,c),B(x,y,z,2,3,Math.min(2,depth),fc));if(!isHead&&y>=29)mass.push(B(x,y,z+depth-2,2,3,2,"blue"));const expanding=d>prev[1],shrinking=d>next[1]||j===sizes.length-1;const part=shrinking?"15068":expanding?"3660b":null;let blocked=isHead&&((y>=55&&y<71&&((x< -5&&x+2> -8)||(x<8&&x+2>5)))||(y>=50&&y<62&&x<3&&x+2> -3));if(part&&!blocked)skin.push(P(part,x,y,z,fc));if(part&&depth>=4)skin.push(P(part,x,y,z+depth-2,isHead?"blue":y>=29?"blue":c,180));}const sidePart=w>next[0]||j===sizes.length-1?"15068":w>prev[0]?"3660b":null;if(sidePart){for(let z=f+6;z+2<=f+d-6;z+=2){skin.push(P(sidePart,l,y,z,c,90),P(sidePart,l+w-2,y,z,c,270));}}}return {mass,skin};}
function foot(x,z){return [floor({at:[x,0,z],size:[6,10],layers:2,colour:"yellow"}),B(x,2,z+3,6,3,7,"yellow"),...range(3).map(i=>P("24309",x+2*i,2,z,"yellow")),floor({at:[x,5,z+3],size:[6,7],colour:"yellow",top:"tile"}),B(x+1,5,z+5,4,3,4,"medium azure")];}
section("Golden webbed feet",[foot(-8,-9),foot(2,-8)]);
const torso=shell(bodySizes,5,false);section("Pear-shaped body",[torso.mass,torso.skin]);
function flipper(rows){const mass=[],skin=[];for(let i=0;i<rows.length;i++){const [x,y,w]=rows[i];mass.push(B(x,y,-2,w,3,4,"medium azure"));for(let k=0;k<w;k++){skin.push(P("11477",x+k,y,-2,"medium azure"),P("11477",x+k,y,0,"medium azure",180));}}return [mass,skin];}
section("One flipper waving",[flipper([[8,26,6],[10,29,6],[12,32,6],[14,35,6],[16,38,6],[17,41,5],[18,44,4],[18,47,2]]),flipper([[-15,11,3],[-15,14,4],[-14,17,5],[-13,20,5],[-12,23,5],[-11,26,5],[-10,29,4]])]);
section("Little swallowtail",[B(-5,14,6,10,6,5,"blue"),B(-4,20,8,8,3,4,"blue"),...[-4,0,4].map((x,i)=>[B(x,14,10,2,3,5,"blue"),P("61678",x,17,11,"blue",180),P("61678",x+1,17,11,"blue",180)]),floor({at:[-3,23,8],size:[6,3],colour:"blue",top:"tile"})]);
const head=shell(headSizes,41,true);section("Round sapphire hood and white face",[head.mass,head.skin]);
function eye(x){return [B(x+1,55,-12,2,3,2,"black"),B(x,58,-12,3,10,2,"black"),P("15068",x,68,-12,"black"),P("11477",x+2,68,-12,"black"),P("3005",x,64,-12,"white"),P("3024",x+2,59,-12,"white")];}
function button(x){return [B(x,20,-9,3,5,2,"white"),...range(3).map(i=>P("24201",x+i,20,-9,"white")),P("15068",x,25,-9,"white"),P("11477",x+2,25,-9,"white")];}
section("Bright eyes and snowy buttons",[eye(-8),eye(5),button(-6),button(3)]);
section("Smiling golden beak",[B(-3,52,-13,6,3,3,"yellow"),...[-3,-1,1].map(x=>P("3660b",x,52,-15,"yellow")),floor({at:[-3,55,-15],size:[6,5],colour:"black"}),B(-3,56,-12,6,3,2,"yellow"),...[-3,-1,1].map(x=>P("24309",x,56,-15,"yellow")),floor({at:[-3,59,-12],size:[6,2],colour:"yellow",top:"tile"})]);
section("Crown finish",[floor({at:[-2,86,-1],size:[4,2],colour:"blue",top:"tile"})]);","seed":1}}

